/**
 * Shared across every Sazabi client SDK so two SDKs bundled into one app
 * recognize each other's wrappers and never double-wrap a primitive.
 */
export const WRAPPED_MARKER = "__sazabiBrowserWrapped";

/** Best-effort idempotency marker on wrapper functions. */
export const markWrapped = (fn: object): void => {
  try {
    Object.defineProperty(fn, WRAPPED_MARKER, { value: true });
  } catch {
    // Non-extensible function object: the idempotency guard degrades gracefully.
  }
};

export const isWrapped = (fn: unknown): boolean =>
  typeof fn === "function" &&
  (fn as unknown as Record<string, unknown>)[WRAPPED_MARKER] === true;
