import {
  type ClientEvent,
  isWrapped,
  markWrapped,
} from "@sazabi/client-sdk-core";

export interface NavigationCaptureOptions {
  emit(event: ClientEvent): void;
  /** Fired on every captured navigation (dead-click signal). */
  onNavigate(): void;
  /**
   * Applied to every page URL the event records (`url.full` and
   * `app.navigation.from`, the referrer included): the core's `redactUrl`
   * with the app's `network.redactQueryParams`. The dedupe compares raw URLs.
   */
  redactUrl(url: string): string;
}

export interface NavigationCaptureHandle {
  teardown(): void;
}

type NavigationType =
  | "load"
  | "pushState"
  | "replaceState"
  | "popstate"
  | "hashchange"
  | "reload";

/**
 * Navigation API `currententrychange` types → our History-API-flavored
 * vocabulary, so queries see one taxonomy regardless of which API navigated.
 */
const NAVIGATION_API_TYPE_MAP: Record<string, NavigationType> = {
  push: "pushState",
  replace: "replaceState",
  traverse: "popstate",
  reload: "reload",
};

// ------------------------------------------------------------- activation --
// History patches install dormant (routers commonly capture
// History.prototype methods at module scope) and consult this slot per call.

interface ActiveNavigation {
  options: NavigationCaptureOptions;
  previousUrl: string;
}

let active: ActiveNavigation | undefined;

const emitNavigation = (navigationType: NavigationType): void => {
  const current = active;
  if (!current) return;
  try {
    const currentUrl = window.location.href;
    const from = current.previousUrl;
    current.previousUrl = currentUrl;
    if (navigationType !== "load" && from === currentUrl) {
      return; // replaceState to the same URL etc. is not a navigation.
    }
    current.options.onNavigate();
    current.options.emit({
      type: "navigation",
      body: `navigation ${window.location.pathname}`,
      severity: "INFO",
      timeUnixMs: Date.now(),
      attributes: {
        "app.navigation.type": navigationType,
        "url.full": current.options.redactUrl(currentUrl),
        "app.navigation.from": from
          ? current.options.redactUrl(from)
          : undefined,
      },
    });
  } catch {
    // Capture failures must never surface to the host.
  }
};

interface HistoryPatch {
  originalPushState: History["pushState"];
  originalReplaceState: History["replaceState"];
  wrappedPushState: History["pushState"];
  wrappedReplaceState: History["replaceState"];
}

let historyPatch: HistoryPatch | undefined;

const makeHistoryPatch = (proto: History): HistoryPatch => {
  const originalPushState = proto.pushState;
  const originalReplaceState = proto.replaceState;

  const wrappedPushState = function (
    this: History,
    ...args: Parameters<History["pushState"]>
  ): void {
    originalPushState.apply(this, args);
    emitNavigation("pushState");
  };

  const wrappedReplaceState = function (
    this: History,
    ...args: Parameters<History["replaceState"]>
  ): void {
    originalReplaceState.apply(this, args);
    emitNavigation("replaceState");
  };

  return {
    originalPushState,
    originalReplaceState,
    wrappedPushState,
    wrappedReplaceState,
  };
};

/**
 * Install dormant history patches around whatever implementations are
 * currently live. Idempotent; re-wraps if a later actor replaced the methods
 * after an earlier install (the displaced wrappers are inert passthroughs).
 */
export const ensureNavigationPatches = (): void => {
  const proto = History.prototype;
  if (!isWrapped(proto.pushState)) {
    const patch = makeHistoryPatch(proto);
    markWrapped(patch.wrappedPushState);
    markWrapped(patch.wrappedReplaceState);
    proto.pushState = patch.wrappedPushState;
    proto.replaceState = patch.wrappedReplaceState;
    historyPatch = patch;
  }
};

/** Restore the natives if the current implementations are still ours. */
export const uninstallNavigationPatches = (): void => {
  const proto = History.prototype;
  if (historyPatch) {
    if (proto.pushState === historyPatch.wrappedPushState) {
      proto.pushState = historyPatch.originalPushState;
    }
    if (proto.replaceState === historyPatch.wrappedReplaceState) {
      proto.replaceState = historyPatch.originalReplaceState;
    }
  }
  historyPatch = undefined;
};

/**
 * SPA navigation capture. Listeners alone miss programmatic navigation,
 * which is most navigation in React apps, so `history.pushState` /
 * `replaceState` are wrapped under the same isolation rules as the network
 * patch.
 */
export const installNavigationCapture = (
  options: NavigationCaptureOptions,
): NavigationCaptureHandle => {
  ensureNavigationPatches();
  active = { options, previousUrl: document.referrer || "" };

  const onPopState = (): void => {
    emitNavigation("popstate");
  };
  const onHashChange = (): void => {
    emitNavigation("hashchange");
  };
  window.addEventListener("popstate", onPopState);
  window.addEventListener("hashchange", onHashChange);

  // Navigation API (Chromium): `navigation.navigate()` same-document
  // navigations call neither pushState nor popstate, but every same-document
  // navigation, whichever API initiated it, fires `currententrychange`.
  // The same-URL dedupe in emitNavigation collapses the overlap with the
  // history patch and legacy listeners; first signal wins.
  const navigationApi = (window as { navigation?: EventTarget }).navigation;
  const onCurrentEntryChange = (event: Event): void => {
    const navigationType = (event as { navigationType?: string | null })
      .navigationType;
    const mapped = NAVIGATION_API_TYPE_MAP[navigationType ?? ""];
    if (mapped) {
      // Unmapped/null types (e.g. updateCurrentEntry metadata edits) are
      // not navigations.
      emitNavigation(mapped);
    }
  };
  navigationApi?.addEventListener("currententrychange", onCurrentEntryChange);

  // The page we landed on is the first navigation of the window.
  emitNavigation("load");

  return {
    teardown() {
      active = undefined;
      window.removeEventListener("popstate", onPopState);
      window.removeEventListener("hashchange", onHashChange);
      navigationApi?.removeEventListener(
        "currententrychange",
        onCurrentEntryChange,
      );
    },
  };
};
