import { createMemoryStore, type SessionStore } from "@sazabi/client-sdk-core";

/**
 * Storage access that degrades to in-memory when storage is unavailable
 * (Safari private mode, disabled cookies, sandboxed iframes). A degraded
 * session is per-page rather than cross-tab, an acceptable fallback.
 */
export const createSafeStorage = (getStore: () => Storage): SessionStore => {
  const memory = createMemoryStore();
  return {
    get(key) {
      try {
        return getStore().getItem(key);
      } catch {
        return memory.get(key);
      }
    },
    set(key, value) {
      try {
        getStore().setItem(key, value);
      } catch {
        memory.set(key, value);
      }
    },
    remove(key) {
      memory.remove(key);
      try {
        getStore().removeItem(key);
      } catch {
        // Fallback store already cleared.
      }
    },
  };
};

/** Absolute request URL as the page resolves it, credentials stripped. */
export const resolveUrl = (raw: string): string | undefined => {
  try {
    const url = new URL(raw, window.location.href);
    url.username = "";
    url.password = "";
    return url.href;
  } catch {
    return undefined;
  }
};

export const isSameOrigin = (resolved: string): boolean => {
  try {
    return new URL(resolved).origin === window.location.origin;
  } catch {
    return false;
  }
};

export const isOffline = (): boolean =>
  typeof navigator !== "undefined" && navigator.onLine === false;

/**
 * React Native aliases `window` to its global, so the server-side guard in
 * init() passes there; without this check the SDK would reach the DOM and
 * throw into the host. The mobile SDK is `@sazabi/react-native`.
 */
export const isReactNativeHost = (): boolean =>
  typeof navigator !== "undefined" &&
  (navigator as { product?: string }).product === "ReactNative";
