/**
 * Absolute-URL parsing with no `URL` global. React Native's built-in `URL`
 * throws "not implemented" for `hostname`, `pathname`, and `origin`, and the
 * core must work there unpolyfilled, so the few fields the SDKs read are
 * parsed here. Only absolute http(s)-style URLs resolve; a binding resolves
 * relative references against its own base before calling in.
 */

export interface ParsedUrl {
  /** e.g. `https:` */
  protocol: string;
  /** host with port, no credentials */
  host: string;
  hostname: string;
  pathname: string;
  search: string;
  hash: string;
  origin: string;
  /** Normalized absolute URL with credentials stripped. */
  href: string;
}

const ABSOLUTE_URL =
  /^([a-z][a-z0-9+.-]*):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/i;

const DEFAULT_PORTS: Record<string, string> = {
  "https:": ":443",
  "http:": ":80",
};

/**
 * `https://host:443` and `https://host` are one origin to every URL parser,
 * so they must be one here too: the browser binding compares a request URL
 * the host normalized against an intake base parsed here, and a default port
 * left in place would let the SDK's own uploads pass as app traffic.
 */
const withoutDefaultPort = ({
  host,
  protocol,
}: {
  host: string;
  protocol: string;
}): string => {
  const suffix = DEFAULT_PORTS[protocol];
  return suffix && host.endsWith(suffix) ? host.slice(0, -suffix.length) : host;
};

export const parseAbsoluteUrl = (raw: string): ParsedUrl | undefined => {
  const match = ABSOLUTE_URL.exec(raw.trim());
  if (!match) return undefined;
  const [, scheme, authority, path, search = "", hash = ""] = match;
  if (!scheme || authority === undefined) return undefined;
  const at = authority.lastIndexOf("@");
  const protocol = `${scheme.toLowerCase()}:`;
  const host = withoutDefaultPort({
    host: (at === -1 ? authority : authority.slice(at + 1)).toLowerCase(),
    protocol,
  });
  if (!host) return undefined;
  const hostname = host.startsWith("[")
    ? host.slice(0, host.indexOf("]") + 1)
    : host.replace(/:\d*$/, "");
  const pathname = path || "/";
  const origin = `${protocol}//${host}`;
  return {
    protocol,
    host,
    hostname,
    pathname,
    search,
    hash,
    origin,
    href: `${origin}${pathname}${search}${hash}`,
  };
};

/**
 * Whether `url` is `base` or lies under it: the same origin (scheme, host,
 * port) and, when the base has a path, that path as whole segments. A string
 * prefix would also match `https://intake.example.com.evil.test/`.
 */
export const isUnderBase = ({
  url,
  base,
}: {
  url: string;
  base: string;
}): boolean => {
  const target = parseAbsoluteUrl(url);
  const root = parseAbsoluteUrl(base);
  if (!target || !root || target.origin !== root.origin) return false;
  const prefix = root.pathname.replace(/\/+$/, "");
  return (
    !prefix ||
    target.pathname === prefix ||
    target.pathname.startsWith(`${prefix}/`)
  );
};
