import {
  activateNetworkCapture,
  deactivateNetworkCapture,
  emitNetworkEvent,
  ensureXhrPatch,
  getActiveNetworkCapture,
  isAborted,
  isAllowedForInjection,
  isWrapped,
  markWrapped,
  type NetworkCaptureOptions,
  readRequestId,
  recordWrapperRequest,
  type RequestTraceContext,
  resetWrapperLedger,
  uninstallXhrPatch,
} from "@sazabi/client-sdk-core";
import { isOffline } from "./host";

export interface NetworkCaptureHandle {
  teardown(): void;
}

// ------------------------------------------------------------------ fetch --
// The browser-only half of network capture. XMLHttpRequest is patched by the
// core (React Native's fetch is an XHR polyfill, so the core owns that patch);
// browsers have a native fetch that bypasses XHR, so it gets its own wrapper
// here. Both consult the core's active slot and share its wrapper-seen ledger.

interface FetchPatch {
  original: typeof fetch;
  wrapped: typeof fetch;
}

let fetchPatch: FetchPatch | undefined;

/**
 * Outermost-wins sandwich guard. When a third party patches fetch between our
 * register-time install and init (Sentry, analytics), init's re-wrap makes
 * the chain ourWrapper2(thirdParty(ourWrapper1(native))): two ACTIVE copies
 * of our wrapper in one call path, which would double-emit every event. The
 * outermost wrapper raises this depth for the synchronous span of its
 * call-through; inner copies see it and become pure passthroughs.
 */
let fetchProcessingDepth = 0;

const makeWrappedFetch = (originalFetch: typeof fetch): typeof fetch => {
  const callThrough = (
    thisArg: unknown,
    input: RequestInfo | URL,
    init?: RequestInit,
  ): Promise<Response> => {
    fetchProcessingDepth++;
    try {
      return originalFetch.call(thisArg, input, init);
    } finally {
      fetchProcessingDepth--;
    }
  };

  return function (
    this: unknown,
    input: RequestInfo | URL,
    init?: RequestInit,
  ): Promise<Response> {
    const options = getActiveNetworkCapture();
    if (!options || fetchProcessingDepth > 0 || isWrapped(originalFetch)) {
      return originalFetch.call(this, input, init);
    }

    let resolvedUrl: string | undefined;
    let method = "GET";
    let injected: RequestTraceContext | undefined;
    let finalInit = init;

    try {
      const rawUrl =
        typeof input === "string"
          ? input
          : input instanceof URL
            ? input.href
            : input.url;
      resolvedUrl = options.resolveUrl(rawUrl);

      if (typeof input === "object" && "method" in input && input.method) {
        method = input.method.toUpperCase();
      }
      if (init?.method) {
        method = init.method.toUpperCase();
      }

      const internal =
        resolvedUrl === undefined || options.isInternalUrl(resolvedUrl);

      if (
        !internal &&
        resolvedUrl &&
        options.propagateTraceContext &&
        isAllowedForInjection(options, resolvedUrl)
      ) {
        const requestContext = options.traceContext.forRequest();

        if (input instanceof Request && init === undefined) {
          // Headers on a constructed Request are mutable for non-forbidden
          // names; if the guard rejects them, skip injection rather than
          // clone (cloning can consume one-shot bodies).
          try {
            for (const [name, value] of Object.entries(
              requestContext.headers,
            )) {
              if (!input.headers.has(name)) {
                input.headers.set(name, value);
              }
            }
            injected = requestContext;
          } catch {
            injected = undefined;
          }
        } else {
          // Per fetch semantics, init.headers replaces the Request's own
          // headers entirely. When the caller passed a Request plus an init
          // WITHOUT headers, seed the merge from the Request so injection
          // does not silently strip Authorization/Content-Type/etc.
          const merged =
            input instanceof Request && init?.headers === undefined
              ? new Headers(input.headers)
              : new Headers(init?.headers);
          let alreadyTraced = merged.has("traceparent");
          if (input instanceof Request && input.headers.has("traceparent")) {
            alreadyTraced = true;
          }
          if (!alreadyTraced) {
            for (const [name, value] of Object.entries(
              requestContext.headers,
            )) {
              merged.set(name, value);
            }
            finalInit = { ...init, headers: merged };
            injected = requestContext;
          }
        }
      }

      if (!internal && resolvedUrl !== undefined) {
        recordWrapperRequest(resolvedUrl);
      }

      if (internal || !options.capture || resolvedUrl === undefined) {
        return callThrough(this, input, finalInit);
      }
    } catch {
      // Any preparation failure: fall through to a plain passthrough call.
      return callThrough(this, input, init);
    }

    const start = performance.now();
    const capturedUrl = resolvedUrl;
    const capturedMethod = method;
    const capturedInjection = injected;
    const capturedSignal =
      finalInit?.signal ??
      (input instanceof Request ? input.signal : undefined);

    return callThrough(this, input, finalInit).then(
      (response) => {
        emitNetworkEvent(options, {
          kind: "fetch",
          method: capturedMethod,
          resolvedUrl: capturedUrl,
          status: response.status,
          durationMs: performance.now() - start,
          injected: capturedInjection,
          ...readRequestId(options, (name) => response.headers.get(name)),
        });
        return response;
      },
      (error: unknown) => {
        const aborted = isAborted(
          error,
          capturedSignal?.aborted === true,
          isOffline(),
        );
        emitNetworkEvent(options, {
          kind: "fetch",
          method: capturedMethod,
          resolvedUrl: capturedUrl,
          status: 0,
          durationMs: performance.now() - start,
          severity: aborted ? "DEBUG" : undefined,
          failureMessage:
            error instanceof Error ? error.message : String(error),
          injected: capturedInjection,
        });
        throw error;
      },
    );
    // Cast: the wrapper implements fetch's call signature only. Some runtime
    // type libs put extra properties on `typeof fetch` (Bun's `preconnect`)
    // that a browser wrapper deliberately does not reproduce.
  } as typeof fetch;
};

// ----------------------------------------------------------------- install --

/**
 * Install dormant fetch/XHR patches around whatever implementations are
 * currently live. Idempotent, and re-wraps when a later actor (test stubs,
 * mocking layers) replaced the primitives after an earlier install; the
 * displaced wrapper is an inert passthrough, so single-processing holds.
 */
export const ensureNetworkPatches = (): void => {
  if (!isWrapped(window.fetch)) {
    const original = window.fetch;
    const wrapped = makeWrappedFetch(original);
    markWrapped(wrapped);
    window.fetch = wrapped;
    fetchPatch = { original, wrapped };
  }
  ensureXhrPatch();
};

/**
 * Restore the natives if the current implementations are still ours; if
 * someone patched on top of us, restoring would clobber them, and the
 * inactive wrappers pass through.
 */
export const uninstallNetworkPatches = (): void => {
  if (fetchPatch && window.fetch === fetchPatch.wrapped) {
    window.fetch = fetchPatch.original;
  }
  fetchPatch = undefined;
  uninstallXhrPatch();
  resetWrapperLedger();
};

export const installNetworkCapture = (
  options: NetworkCaptureOptions,
): NetworkCaptureHandle => {
  ensureNetworkPatches();
  activateNetworkCapture(options);

  return {
    teardown() {
      deactivateNetworkCapture();
    },
  };
};
